import { algoliasearch } from 'algoliasearch';

console.log(algoliasearch); // ¿Qué muestra?

const client = algoliasearch('OSJISXEYU4', '7b29281d589f9f5e2b597c36e288d713');
console.log(client); // ¿Qué muestra?

const index = client.initIndex('pet');
export default index;
